#![cfg(feature="test-hook")]
#[path="../src/semantic.rs"] mod semantic;
use semantic::SemanticService;use std::{sync::mpsc,thread,time::{Duration,Instant}};
#[test] #[ignore = "requires local EmbeddingGemma model and llama-server"] fn cancel_before_publish_preserves_old_index(){let p=std::env::temp_dir().join(format!("atlas-progress-race-{}",std::process::id()));atlas_native_storage_contract::create_workspace(&p).unwrap();let(ready_tx,ready_rx)=mpsc::channel();let(resume_tx,resume_rx)=mpsc::channel();let s=SemanticService::start_with_hook("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf",ready_tx,resume_rx).unwrap();s.enqueue(&p,None).unwrap();ready_rx.recv_timeout(Duration::from_secs(120)).unwrap();s.cancel(&p);assert_eq!(s.status(&p)["stopping"],true);resume_tx.send(()).unwrap();let end=Instant::now()+Duration::from_secs(20);while Instant::now()<end && s.status(&p)["stopping"]==true{thread::sleep(Duration::from_millis(50));}assert_eq!(s.status(&p)["cancelled"],true);assert!(!p.join(".atlas-semantic-native/current").exists());s.close(&p).unwrap();std::fs::remove_dir_all(p).unwrap();}
